// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

/**
 * Placement computation for fragments in factorized execution (fragment-fusion M5), consolidating the vocabulary the
 * engine already uses: per-depth availability masks (the {@code analyzeSplit} {@code fresh}/{@code reads} model, where
 * depth {@code d}'s mask holds every engine slot bound at or above {@code d}) against a fragment's
 * {@link PlacementContract#requiredColumns()}. The lowest legal node is the shallowest depth whose available columns
 * cover the requirement — evaluating there lets one physical rejection remove that value's whole logical multiplicity
 * (multiplicity-amplified filtering). A requirement no single depth covers (variables in independent sibling groups) is
 * illegal everywhere and must be evaluated after flattening; this method never places it.
 */
public final class FragmentPlacement {

	private FragmentPlacement() {
	}

	/** Result of {@link #lowestLegalDepth}: no single depth covers the requirement. */
	public static final int NO_LEGAL_DEPTH = -1;

	/**
	 * The shallowest depth whose cumulative available-column mask covers {@code requiredColumns}, or
	 * {@link #NO_LEGAL_DEPTH}. {@code availableByDepth[d]} must be the mask of every column addressable at depth
	 * {@code d} (cumulative by construction in the engine's split model).
	 */
	public static int lowestLegalDepth(long requiredColumns, long[] availableByDepth) {
		for (int depth = 0; depth < availableByDepth.length; depth++) {
			if ((requiredColumns & ~availableByDepth[depth]) == 0L) {
				return depth;
			}
		}
		return NO_LEGAL_DEPTH;
	}

	/**
	 * Records one factorized fragment evaluation in the multiplicity-aware telemetry: {@code physicalRejections} values
	 * rejected, each representing {@code multiplicity} logical rows. {@code rfTest}/{@code rfAccept}-style physical
	 * counters alone misprice factorized predicates — 100 physical tests eliminating 10M logical rows is radically
	 * different from 100 tests eliminating 100 rows.
	 */
	public static void recordFactorizedRejection(long physicalRejections, long multiplicity) {
		FragmentTelemetry.PHYSICAL_REJECTIONS.add(physicalRejections);
		FragmentTelemetry.LOGICAL_MULTIPLICITY_REJECTED.add(Math.multiplyExact(physicalRejections, multiplicity));
	}
}
